import{_ as e,o,c as t,ag as r}from"./chunks/framework.Cyu1VozZ.js";const p=JSON.parse('{"title":"Using the Board","description":"","frontmatter":{},"headers":[],"relativePath":"board/using-the-board.md","filePath":"board/using-the-board.md"}'),n={name:"board/using-the-board.md"};function s(i,a,l,d,c,h){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="using-the-board" tabindex="-1">Using the Board <a class="header-anchor" href="#using-the-board" aria-label="Permalink to &quot;Using the Board&quot;">​</a></h1><p>A <strong>board</strong> is an infinite, freeform canvas — a Miro/FigJam-style whiteboard for sketching ideas, arranging sticky notes, and collaborating in real time. Unlike a slide, a board has no fixed page size: you pan and zoom across a boundless plane.</p><h2 id="create-a-board" tabindex="-1">Create a board <a class="header-anchor" href="#create-a-board" aria-label="Permalink to &quot;Create a board&quot;">​</a></h2><ol><li>Open your workspace</li><li>Click the <strong>New</strong> dropdown button</li><li>Select <strong>New Board</strong></li></ol><p>The board opens with an empty canvas and appears in your workspace document list.</p><h2 id="move-around-the-canvas" tabindex="-1">Move around the canvas <a class="header-anchor" href="#move-around-the-canvas" aria-label="Permalink to &quot;Move around the canvas&quot;">​</a></h2><ul><li><strong>Scroll / trackpad</strong> to pan across the canvas</li><li><strong>Zoom</strong> in and out to move between the big picture and the details</li><li>The <strong>minimap</strong> in the corner shows the whole board at a glance; drag within it to jump to another area</li></ul><h2 id="add-content" tabindex="-1">Add content <a class="header-anchor" href="#add-content" aria-label="Permalink to &quot;Add content&quot;">​</a></h2><p>Pick a tool from the toolbar:</p><ul><li><strong>Select</strong> (<code>Esc</code>) — select, move, and resize existing items</li><li><strong>Text box</strong> — drop freeform text anywhere on the canvas</li><li><strong>Sticky note</strong> — add a colored sticky; the color swatch next to the tool opens a 6-color palette, and text inside a sticky shrinks to fit</li><li><strong>Insert image</strong> — add an image from your computer (you can also paste or drag an image straight onto the canvas)</li></ul><h2 id="collaborate" tabindex="-1">Collaborate <a class="header-anchor" href="#collaborate" aria-label="Permalink to &quot;Collaborate&quot;">​</a></h2><p>Boards sync in real time through the same collaboration engine as the rest of Wafflebase. Everyone editing a board sees each other&#39;s live cursors, and changes appear instantly for all viewers.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Share a board the same way as any other document — see <a href="/docs/guide/collaboration.html">Collaboration &amp; Sharing</a>. Viewers with read-only access can still pan and zoom around the board.</p></div>',13)])])}const u=e(n,[["render",s]]);export{p as __pageData,u as default};
